     8→
     9→// FindStanza locates a named stanza in content.
    10→// Returns version, body, found. If not found, version=-1, body="", found=false.
    11→func FindStanza(content, name string) (version int, body string, found bool) {
    12→	beginPrefix := "# BEGIN " + name + " (v"
    13→	endLine := "# END " + name
    14→
    15→	lines := strings.Split(content, "\n")
    16→	inStanza := false
    17→	stanzaVersion := -1
    18→	var bodyLines []string
    19→
    20→	for _, line := range lines {
    21→		trimmed := strings.TrimSpace(line)
    22→		if !inStanza {
    23→			if strings.HasPrefix(trimmed, beginPrefix) && strings.HasSuffix(trimmed, ")") {
    24→				// Extract version number
    25→				vStr := trimmed[len(beginPrefix) : len(trimmed)-1]
    26→				v, err := strconv.Atoi(vStr)
    27→				if err != nil {
    28→					continue
    29→				}
    30→				inStanza = true
    31→				stanzaVersion = v
    32→				bodyLines = nil
    33→				continue
    34→			}
    35→		} else {
    36→			if trimmed == endLine {
    37→				return stanzaVersion, strings.Join(bodyLines, "\n"), true
    38→			}
    39→			bodyLines = append(bodyLines, line)
    40→		}
    41→	}
    42→
    43→	return -1, "", false
    44→}
    45→
    46→// UpsertStanza inserts or replaces a named stanza. Returns new file content.
    47→func UpsertStanza(content string, name string, version int, body string) string {
    48→	beginPrefix := "# BEGIN " + name + " (v"
    49→	endLine := "# END " + name
    50→	beginLine := fmt.Sprintf("# BEGIN %s (v%d)", name, version)
    51→
    52→	stanzaBlock := beginLine + "\n" + body + "\n" + endLine
    53→
    54→	lines := strings.Split(content, "\n")
    55→	var result []string
    56→	inStanza := false
    57→	replaced := false
    58→
    59→	for _, line := range lines {
    60→		trimmed := strings.TrimSpace(line)
    61→		if !inStanza {
    62→			if strings.HasPrefix(trimmed, beginPrefix) && strings.HasSuffix(trimmed, ")") {
    63→				// Validate it has a version number
    64→				vStr := trimmed[len(beginPrefix) : len(trimmed)-1]
    65→				if _, err := strconv.Atoi(vStr); err != nil {
    66→					result = append(result, line)
    67→					continue
    68→				}
    69→				inStanza = true
    70→				// Add the replacement stanza
    71→				result = append(result, stanzaBlock)
    72→				replaced = true
    73→				continue
    74→			}
    75→			result = append(result, line)
    76→		} else if trimmed == endLine {
    77→			inStanza = false
    78→			// Skip old stanza lines (already replaced)
    79→		}
    80→	}
    81→
    82→	if !replaced {
    83→		// Append to end, ensuring a blank line separator
    84→		trimmedContent := strings.TrimRight(content, "\n")
    85→		if trimmedContent == "" {
    86→			return stanzaBlock + "\n"
    87→		}
    88→		return trimmedContent + "\n\n" + stanzaBlock + "\n"
    89→	}
    90→
    91→	return strings.Join(result, "\n")
    92→}
    93→
    94→// RemoveStanza removes a named stanza. Returns content unchanged if not found.
    95→func RemoveStanza(content, name string) string {
    96→	beginPrefix := "# BEGIN " + name + " (v"
    97→	endLine := "# END " + name
    98→
    99→	lines := strings.Split(content, "\n")
   100→	var result []string
   101→	inStanza := false
   102→	found := false
   103→	// Track index where stanza starts to remove preceding blank line
   104→	stanzaStartIdx := -1
   105→
   106→	for _, line := range lines {
   107→		trimmed := strings.TrimSpace(line)
   108→		if !inStanza {
   109→			if strings.HasPrefix(trimmed, beginPrefix) && strings.HasSuffix(trimmed, ")") {
   110→				// Validate it has a version number
   111→				vStr := trimmed[len(beginPrefix) : len(trimmed)-1]
   112→				if _, err := strconv.Atoi(vStr); err != nil {
   113→					result = append(result, line)
   114→					continue
   115→				}
   116→				inStanza = true
   117→				found = true
   118→				stanzaStartIdx = len(result)
   119→				continue
   120→			}
   121→			result = append(result, line)
   122→		} else if trimmed == endLine {
   123→			inStanza = false
   124→		}
   125→		// Skip stanza body lines when inStanza
   126→	}
   127→
   128→	if !found {
   129→		return content
   130→	}
   131→
   132→	// Remove blank line before the stanza if it exists
   133→	if stanzaStartIdx > 0 && strings.TrimSpace(result[stanzaStartIdx-1]) == "" {
   134→		result = append(result[:stanzaStartIdx-1], result[stanzaStartIdx:]...)
   135→	}
   136→
   137→	// Clean up trailing empty lines — keep at most one trailing newline
   138→	output := strings.Join(result, "\n")
   139→	output = strings.TrimRight(output, "\n")
   140→	if output != "" {
   141→		output += "\n"
   142→	}
   143→
   144→	return output
   145→}
